CREATE TABLE IF NOT EXISTS workflow_alerts(id TEXT PRIMARY KEY,rule TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,country_code TEXT NOT NULL,message TEXT NOT NULL,severity TEXT NOT NULL DEFAULT 'medium',status TEXT NOT NULL DEFAULT 'open',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,acknowledged_by TEXT REFERENCES users(id),acknowledged_at TEXT,UNIQUE(rule,entity_type,entity_id));
